import numpy as np

class TinyStore:
    def __init__(self):
        self.records = []
    def upsert(self, records):
        self.records.extend(records)
    def query(self, q, k=2):
        q = np.array(q, dtype=float)
        scored = []
        for r in self.records:
            v = np.array(r["vector"], dtype=float)
            score = float(q @ v / (np.linalg.norm(q) * np.linalg.norm(v)))
            scored.append({"id": r["id"], "text": r["text"], "score": score})
        scored.sort(key=lambda r: r["score"], reverse=True)
        return scored[:k]

store = TinyStore()
store.upsert([
    {"id": "c0", "vector": [1.0, 0.0, 0.0], "text": "refunds take 14 days"},
    {"id": "c1", "vector": [0.0, 1.0, 0.0], "text": "store opens at 9am"},
    {"id": "c2", "vector": [0.9, 0.1, 0.0], "text": "refund policy details"},
])
for h in store.query([1.0, 0.05, 0.0], k=2):
    print(h["id"], round(h["score"], 3), h["text"])

