        self.records = []
    def upsert(self, records):
        self.records.extend(records)
    def _match(self, meta, where):
        return all(meta.get(k) == v for k, v in where.items())
    def query(self, q, k=2, where=None):
        where = where or {}
        q = np.array(q, dtype=float)
        hits = []
        for r in self.records:
            if not self._match(r.get("metadata", {}), where):
                continue                        # filtered out before scoring
            v = np.array(r["vector"], dtype=float)
            s = float(q @ v / (np.linalg.norm(q) * np.linalg.norm(v)))
            hits.append({"id": r["id"], "score": s})
        hits.sort(key=lambda r: r["score"], reverse=True)
        return hits[:k]

store = FilterStore()
