import numpy as np

class MiniStore:
    def __init__(self):
        self._by_id = {}   # id -> record, so re-upsert updates in place

    def upsert(self, records):
        for r in records:
            self._by_id[r["id"]] = r

    @staticmethod
    def _cosine(a, b):
        a, b = np.array(a, dtype=float), np.array(b, dtype=float)
        denom = np.linalg.norm(a) * np.linalg.norm(b)
        return float(a @ b / denom) if denom else 0.0

    @staticmethod
    def _match(meta, where):
        return all(meta.get(key) == val for key, val in where.items())

    def query(self, vector, k, where=None):
        where = where or {}
        hits = []
        for r in self._by_id.values():
            if not self._match(r.get("metadata", {}), where):
                continue
            score = self._cosine(vector, r["vector"])
            hits.append({"id": r["id"], "text": r["text"], "score": score})
        hits.sort(key=lambda h: h["score"], reverse=True)
        return hits[:k]

